   const activeJobId = activeJob?.id ?? "";
   const steps = (canvas?.steps ?? []).filter(
     (step) => !activeJobId || !step.job_id || step.job_id === activeJobId,
   );
   async function saveStep(stepId: string) {
     if (!editStepName.trim()) {
       return;
