 :root {
   color-scheme: dark;
   --bg: #0a0b0e;
   --bg-raised: #0e1014;
   --text: #f1f2f4;
   --muted: #a2a7b3;
   --faint: #71767f;
   --accent: #8b8cf8;
   --accent-strong: #6366f1;
   --green: #4ade80;
   --amber: #f0b34a;
   --line: rgba(255, 255, 255, 0.07);
   --line-strong: rgba(255, 255, 255, 0.14);
   --surface: rgba(255, 255, 255, 0.03);
   --surface-hover: rgba(255, 255, 255, 0.06);
   --font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
   --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
 }

 * {
   box-sizing: border-box;
 }

 html,
 body,
 #root {
   height: 100%;
 }

 body {
   margin: 0;
   background: var(--bg);
   color: var(--text);
   font-family: var(--font);
   -webkit-font-smoothing: antialiased;
 }

 button,
 input,
 select,
 textarea {
   font-family: inherit;
   color: inherit;
 }

 button {
   -webkit-tap-highlight-color: transparent;
 }

 a {
   color: #a5b4fc;
   text-decoration: underline;
   text-underline-offset: 2px;
 }

 :focus-visible {
   outline: 2px solid var(--accent);
   outline-offset: 2px;
 }

 .sr-only {
   position: absolute;
   width: 1px;
   height: 1px;
   padding: 0;
   margin: -1px;
   overflow: hidden;
   clip: rect(0, 0, 0, 0);
   white-space: nowrap;
   border: 0;
 }

 /* ------------------------------------------------------------------ */
 /* Shell                                                              */
 /* ------------------------------------------------------------------ */
 .studio-app {
   height: 100dvh;
   display: flex;
   flex-direction: column;
   background: var(--bg);
   overflow: hidden;
 }

 .scrim {
   position: fixed;
   inset: 0;
   z-index: 50;
   border: 0;
   padding: 0;
   background: rgba(0, 0, 0, 0.55);
   backdrop-filter: blur(2px);
   cursor: default;
 }

 /* ------------------------------------------------------------------ */
 /* Stage                                                              */
 /* ------------------------------------------------------------------ */
 .stage {
   display: flex;
   flex-direction: column;
   flex: 1;
   min-width: 0;
   min-height: 0;
   background:
     radial-gradient(760px 420px at 50% 108%, rgba(99, 102, 241, 0.09), transparent 72%),
     radial-gradient(900px 520px at 68% -12%, rgba(99, 102, 241, 0.08), transparent 68%);
 }

 .bar {
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: 12px;
   flex: none;
   height: 56px;
   padding: 0 18px;
 }

 .bar__left,
 .bar__right {
   display: flex;
   align-items: center;
   gap: 8px;
   min-width: 0;
 }

 .bar__brand {
   padding: 4px 8px;
   border: 0;
   border-radius: 8px;
   background: transparent;
   font: inherit;
   font-size: 0.8rem;
   color: var(--muted);
   white-space: nowrap;
   cursor: pointer;
 }

 .bar__brand:hover {
   background: var(--surface-hover);
   color: var(--text);
 }

 .bar__health {
   display: inline-flex;
   align-items: center;
   gap: 7px;
   padding: 5px 11px;
   border: 1px solid var(--line);
   border-radius: 999px;
   background: transparent;
   color: var(--faint);
   font-size: 0.72rem;
   cursor: pointer;
 }

 .bar__health:hover {
   color: var(--muted);
   border-color: var(--line-strong);
 }

 /* ------------------------------------------------------------------ */
 /* Conversation                                                       */
 /* ------------------------------------------------------------------ */
 .chat {
   display: flex;
   flex-direction: column;
   flex: 1;
   min-width: 0;
   min-height: 0;
 }

 .chat__welcome {
   display: flex;
   justify-content: center;
   flex: 1;
   min-height: 0;
   padding: 12px 22px 56px;
   overflow-y: auto;
 }

 .chat__welcome-inner {
   display: flex;
   flex-direction: column;
   gap: 28px;
   width: 100%;
   max-width: 720px;
   /* auto block margins centre when there is room and scroll when there isn't */
   margin-block: auto;
 }

 /* Sits the hero + composer a little above the bottom edge on tall screens. */
 .chat--empty .chat__welcome {
   padding-bottom: max(56px, 14vh);
 }

 .chat__scroll {
   flex: 1;
   min-height: 0;
   overflow-y: auto;
   padding: 6px 22px 20px;
   scrollbar-gutter: stable;
 }

 .chat__thread {
