   height: 12px;
   margin-bottom: 8px;
 }

 @keyframes shimmer {
   0% {
     background-position: -200% 0;
   }
   100% {
     background-position: 200% 0;
   }
 }

 @keyframes hero-in {
   from {
     opacity: 0;
     transform: translateY(6px);
     filter: blur(2px);
