 }

 .ui-list--check li::before {
   content: "✓";
   color: var(--studio-green);
   margin-right: 7px;
   font-size: 0.8em;
 }

 .ui-divider {
   border: none;
   border-top: 1px solid var(--studio-border);
   margin: 2px 0;
   width: 100%;
 }

 /* Actions */
 .ui-actions {
   display: flex;
   flex-wrap: wrap;
   gap: 8px;
 }

 .ui-action {
   border: 1px solid transparent;
   border-radius: 8px;
   padding: 7px 12px;
   font-size: 0.82rem;
   font-weight: 500;
   cursor: pointer;
   transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease,
     transform 0.1s ease;
 }

 .ui-action--primary {
   background: var(--studio-indigo-strong);
   border-color: rgba(255, 255, 255, 0.08);
   color: #fff;
 }

 .ui-action--primary:hover {
   background: #7c7ff5;
 }

 .ui-action--ghost {
   background: transparent;
   border-color: var(--studio-border);
   color: #cbd5e1;
 }

 .ui-action--ghost:hover {
   border-color: rgba(129, 140, 248, 0.45);
   color: var(--studio-text);
 }

 .ui-action:active {
   transform: translateY(1px);
 }

 .ui-action:disabled {
   opacity: 0.5;
   cursor: not-allowed;
   transform: none;
 }

 /* Tables */
 .ui-table-wrap {
   overflow-x: auto;
 }

 .ui-table {
   width: 100%;
   border-collapse: collapse;
   font-size: 0.86rem;
 }

 .ui-table th {
   padding: 0 0 6px;
   border-bottom: 1px solid var(--studio-border);
   text-align: left;
   font-size: 0.66rem;
   font-weight: 600;
   letter-spacing: 0.08em;
   text-transform: uppercase;
   color: var(--studio-muted);
 }

 .ui-table td {
   padding: 9px 0;
   border-bottom: 1px solid rgba(255, 255, 255, 0.04);
   vertical-align: top;
 }

 .ui-table tr:last-child td {
   border-bottom: none;
 }

 .ui-table td:first-child {
   padding-right: 12px;
 }

 .ui-table td:last-child {
   text-align: right;
   white-space: nowrap;
 }

 .ui-table .ui-card__id {
   display: block;
 }

 .ui-table__statement {
   display: block;
   margin-top: 3px;
   line-height: 1.4;
   color: #cbd5e1;
 }

 .ui-table__row--urgent .ui-card__id {
   color: var(--studio-amber);
 }

 /* Impact simulation */
 .ui-bet {
   display: flex;
   align-items: baseline;
   gap: 8px;
   padding: 9px 12px;
   border-radius: 8px;
   border: 1px solid rgba(129, 140, 248, 0.2);
   background: rgba(129, 140, 248, 0.07);
 }

 .ui-bet__label {
   font-size: 0.64rem;
   letter-spacing: 0.08em;
   text-transform: uppercase;
   color: var(--studio-indigo);
   white-space: nowrap;
 }

 .ui-bet__value {
   font-size: 0.88rem;
   color: #e2e8f0;
 }

 .ui-phase {
   padding: 12px;
   border-radius: 10px;
   border: 1px solid;
   min-width: 0;
 }

 .ui-phase.ui-tone--critical {
   background: rgba(248, 113, 113, 0.06);
   border-color: rgba(248, 113, 113, 0.22);
 }

 .ui-phase.ui-tone--positive {
   background: rgba(52, 211, 153, 0.06);
   border-color: rgba(52, 211, 153, 0.22);
 }

 .ui-phase__label {
   margin-bottom: 7px;
   font-size: 0.64rem;
   letter-spacing: 0.09em;
   text-transform: uppercase;
   color: var(--studio-muted);
 }

 .ui-phase__items {
   margin: 0;
   padding-left: 16px;
   display: flex;
   flex-direction: column;
   gap: 5px;
   font-size: 0.84rem;
   color: #cbd5e1;
 }

 /* Evidence */
 .ui-quote {
   margin: 0;
   padding-left: 12px;
   border-left: 2px solid rgba(129, 140, 248, 0.5);
   font-size: 0.95rem;
   font-style: italic;
   line-height: 1.55;
   color: #e2e8f0;
 }

 /* Job map */
 .ui-jobmap {
   list-style: none;
   margin: 0;
   padding: 0;
 }

 .ui-jobmap__step {
   display: flex;
   gap: 10px;
   padding: 8px 0;
   border-bottom: 1px solid rgba(255, 255, 255, 0.04);
 }

 .ui-jobmap__step:last-child {
   border-bottom: none;
 }

 .ui-jobmap__index {
   flex: none;
   display: grid;
   place-items: center;
   width: 20px;
   height: 20px;
   border-radius: 6px;
   background: rgba(129, 140, 248, 0.14);
   color: var(--studio-indigo);
   font-size: 0.7rem;
   font-weight: 700;
   font-variant-numeric: tabular-nums;
 }

 .ui-jobmap__body {
   display: flex;
   flex-direction: column;
   gap: 2px;
 }

 .ui-jobmap__name {
   font-size: 0.88rem;
 }

 .ui-jobmap__stage {
   font-size: 0.64rem;
   letter-spacing: 0.08em;
   text-transform: uppercase;
   color: var(--studio-muted);
 }

 .ui-jobmap__note {
   font-size: 0.78rem;
   color: var(--studio-muted);
 }

 /* Decision record */
 .ui-fields {
   margin: 0;
   display: flex;
   flex-direction: column;
   gap: 10px;
 }

 .ui-field {
   display: flex;
   flex-direction: column;
   gap: 2px;
 }

 .ui-field dt {
   font-size: 0.64rem;
   letter-spacing: 0.08em;
   text-transform: uppercase;
   color: var(--studio-muted);
 }

 .ui-field dd {
   margin: 0;
   font-size: 0.88rem;
   color: #e2e8f0;
 }

 @media (max-width: 640px) {
   .ui-grid--2,
   .ui-grid--3 {
     grid-template-columns: minmax(0, 1fr);
   }
 }

 @media (prefers-reduced-motion: reduce) {
   .ui-surface {
     animation: none;
   }

   .ui-meter__fill {
     transition: none;
   }
 }

 /* Markdown inside a surface. Cards are dense; paragraphs should hug. */
 .ui-card .md-paragraph,
 .ui-callout__body .md-paragraph,
 .ui-card__evidence .md-paragraph,
 .ui-quote .md-paragraph {
   margin: 0 0 6px;
 }

 .ui-card .md-paragraph:last-child,
 .ui-callout__body .md-paragraph:last-child,
 .ui-card__evidence .md-paragraph:last-child,
 .ui-quote .md-paragraph:last-child {
   margin-bottom: 0;
 }

 .ui-card .md-list,
 .ui-callout__body .md-list {
   margin: 4px 0 0;
 }

 /* A surface sits in the prose, not outside it. */
 .message__body > .ui-surface {
   margin: 12px 0;
 }

 /* ------------------------------------------------------------------ */
