 }

 .brand--home:hover .brand__wordmark {
   color: var(--text);
 }

 .brand__wordmark {
   color: var(--muted);
   font-size: 0.88rem;
   font-weight: 600;
   letter-spacing: -0.01em;
   white-space: nowrap;
   transition: color 0.14s ease;
 }

 .brand__mark {
   display: grid;
   place-items: center;
   width: 32px;
   height: 32px;
   flex: none;
   overflow: hidden;
   border-radius: 9px;
   background: var(--odi-tile, #131722);
