 }

 .icon-button {
   position: relative;
   display: inline-grid;
   place-items: center;
   width: 32px;
   height: 32px;
   flex: none;
   border: 1px solid transparent;
   border-radius: 9px;
   background: transparent;
   color: var(--muted);
   cursor: pointer;
   transition:
     background 0.14s ease,
