 }

 .status-dot {
   width: 7px;
   height: 7px;
   flex: none;
   border-radius: 50%;
   background: var(--green);
   box-shadow: 0 0 0 3px rgba(74, 222, 128, 0.12);
 }

 .status-dot.is-warn {
   background: var(--amber);
   box-shadow: 0 0 0 3px rgba(240, 179, 74, 0.14);
 }

 .status-dot.is-unknown {
   background: #5b616c;
   box-shadow: none;
 }

 .bar__bell {
   position: relative;
 }

 .stage__split {
   display: flex;
   flex: 1;
   min-width: 0;
   min-height: 0;
 }

 .stage__thread {
   display: flex;
   flex-direction: column;
   flex: 1;
   min-width: 0;
   min-height: 0;
 }

 /* ------------------------------------------------------------------ */
 /* Rail: what the thread has made, above the thread                   */
 /* ------------------------------------------------------------------ */
 .rail {
   flex: none;
   padding: 0 22px;
 }

 .rail__list {
   display: flex;
   align-items: center;
   gap: 2px;
   width: 100%;
   max-width: 720px;
   margin: 0 auto;
   padding: 0 0 6px;
   list-style: none;
   overflow-x: auto;
   scrollbar-width: none;
   animation: fade-in 0.24s ease;
 }

 .rail__list::-webkit-scrollbar {
   display: none;
 }

 .rail__chip {
   display: inline-flex;
   align-items: center;
   gap: 7px;
   padding: 5px 9px;
   border: 1px solid transparent;
   border-radius: 8px;
   background: transparent;
   color: var(--faint);
   font-size: 0.76rem;
   white-space: nowrap;
