 .memory-list {
   display: flex;
   flex-direction: column;
   gap: 8px;
   margin: 0;
   padding: 0;
   list-style: none;
 }

 .memory-item {
   display: flex;
   flex-direction: column;
   gap: 6px;
   padding: 12px 14px;
   border: 1px solid var(--line);
   border-radius: 10px;
   background: var(--surface);
 }

 .memory-item--suggested {
   border-color: rgba(240, 179, 74, 0.28);
   background: rgba(240, 179, 74, 0.05);
 }

 .memory-item__head {
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: 8px;
 }

 .memory-item__kind {
   margin: 0;
   color: var(--faint);
   font-size: 0.68rem;
   font-weight: 600;
   letter-spacing: 0.05em;
   text-transform: uppercase;
 }

 .memory-item__text {
   margin: 0;
   font-size: 0.9rem;
   line-height: 1.5;
 }

 .memory-item__actions {
   display: flex;
   flex-wrap: wrap;
   align-items: center;
   gap: 10px;
   margin-top: 4px;
 }

 .memory-item__button {
   padding: 5px 10px;
   font-size: 0.78rem;
 }

 .memory-foot {
   display: flex;
   flex-direction: column;
   gap: 10px;
   padding-top: 14px;
   border-top: 1px solid var(--line);
 }

 .memory-foot__note {
   margin: 0;
   color: var(--muted);
   font-size: 0.78rem;
   line-height: 1.5;
 }

 .memory-foot__confirm {
   display: flex;
   flex-direction: column;
   gap: 10px;
   color: var(--text);
   font-size: 0.86rem;
 }

 .memory-foot__confirm p {
   margin: 0;
 }

 .memory-foot__actions {
   display: flex;
   flex-wrap: wrap;
   gap: 8px;
 }


 .ui-card--thesis .ui-card__title {
   font-size: 1.05rem;
   line-height: 1.4;
 }

 .ui-thesis__gap {
   margin: 0;
   color: var(--studio-muted);
   font-size: 0.86rem;
   line-height: 1.5;
 }

 .ui-thesis__claim {
   margin: 0;
   padding: 10px 12px;
   border-left: 2px solid var(--studio-indigo);
   background: rgba(139, 140, 248, 0.06);
   font-size: 0.92rem;
   line-height: 1.55;
 }

 .memory-edit {
   display: flex;
   flex-direction: column;
   gap: 8px;
 }

 .memory-edit__input,
 .memory-add textarea,
 .memory-add select {
   width: 100%;
   padding: 8px 10px;
   border: 1px solid var(--line);
   border-radius: 8px;
   background: var(--bg-raised);
   color: var(--text);
   font: inherit;
   font-size: 0.86rem;
 }

 .memory-add {
   display: flex;
   flex-direction: column;
   gap: 10px;
   padding: 12px 14px;
   border: 1px solid var(--line);
   border-radius: 10px;
   background: var(--surface);
 }

 .memory-add__field {
   display: flex;
   flex-direction: column;
   gap: 6px;
   color: var(--muted);
   font-size: 0.78rem;
 }

 .memory-item__head .memory-item__actions {
   margin-top: 0;
 }

